// Frontend configuration that imports from root config
import rootConfig from '../../config.js';

// Re-export the backend configuration for frontend use
export const backend = rootConfig.backend;
export const frontend = rootConfig.frontend;

// Helper functions for common URL operations
export const getApiUrl = (endpoint = '') => {
  return `${backend.apiURL}${endpoint}`;
};

export const getUploadsUrl = (filename = '') => {
  return `${backend.uploadsURL}/${filename}`;
};

export const getBackendUrl = (path = '') => {
  return `${backend.baseURL}${path}`;
};

export default rootConfig;
